/** Drafts do not create receivables. Issuance freezes recipient, prices, tax treatment and PDF together. */
final class OutgoingInvoices
{
 public const UNITS=['C62'=>'Stück','HUR'=>'Stunden','DAY'=>'Tage','MON'=>'Monate','KGM'=>'kg','LTR'=>'Liter','MTR'=>'Meter','SET'=>'Sätze'];
 public function __construct(private PDO $db,private string $actor){}
 private function access(bool $write=false):array{return Permissions::finance($this->db,$this->actor,$write);}
 private function tx(callable $fn):mixed{return $this->write($fn);}
 private function write(callable $operation):mixed{
  $club=$this->q('SELECT club_id FROM actors WHERE id=?',[$this->actor])->fetchColumn();if(!is_string($club)||$club==='')throw new DomainException('Aktuelle Finanzberechtigung erforderlich.',403);
  try{return Transactions::run($this->db,function()use($operation,$club):mixed{if(!$this->q('SELECT id FROM clubs WHERE id=? FOR UPDATE NOWAIT',[$club])->fetchColumn())throw new DomainException('Eigenen aktiven Verein auswählen.',403);$a=$this->access(true);if($a['club_id']!==$club)throw new DomainException('Vereinszuordnung inzwischen geändert.',403);return$operation();});}
  catch(\PDOException$failure){if(in_array((int)($failure->errorInfo[1]??0),[1205,3572],true))throw new DomainException('Ausgangsrechnung wird gerade bearbeitet. Bitte erneut prüfen.',503,$failure);throw$failure;}
 }
 private function q(string $sql,array $args=[]):\PDOStatement{return DocumentCatalog::query($this->db,$sql,$args);}
 private static function text(array $a,string $key,int $limit,bool $required=true):string{$v=$a[$key]??'';if(!is_string($v)||mb_strlen($v)>$limit||preg_match('/[\x00-\x08\x0b\x0c\x0e-\x1f]/',$v)||($required&&trim($v)===''))throw new DomainException('Bitte „'.(['buyer_name'=>'Name / Firma','buyer_street'=>'Straße und Hausnummer','buyer_postcode'=>'Postleitzahl','buyer_city'=>'Ort','buyer_email'=>'E-Mail','description'=>'Beschreibung','quantity'=>'Menge','unit_gross'=>'Bruttopreis','document_date'=>'Rechnungsdatum','delivery_date'=>'Leistungsdatum','due_date'=>'Fälligkeit','category'=>'Rechnungszweck'][$key]??$key).'“ ausfüllen bzw. prüfen.');return trim($v);}
 private static function date(string $v):string{if(!TaxCatalog::documentYear($v))throw new DomainException('Datum prüfen.');return $v;}
 public static function quantity(string $v):int{if(!preg_match('/^([0-9]{1,6})(?:[,.]([0-9]{1,3}))?$/D',$v,$m))throw new DomainException('Menge positiv mit höchstens drei Nachkommastellen eingeben.');$n=(int)$m[1]*1000+(int)str_pad($m[2]??'',3,'0');if($n<=0)throw new DomainException('Menge muss größer als null sein.');return $n;}
 public static function quantityText(int $n):string{return rtrim(rtrim(number_format($n/1000,3,'.',''),'0'),'.');}
 public static function amount(int $n):string{return number_format($n/100,2,'.','');}
 /** floor(a*b/d) without an overflowing intermediate product. */
 private static function proportion(int $a,int $b,int $d):int{$q=intdiv($a,$d);$r=$a%$d;$answer=0;$carry=0;while($b>0){if($b%2){$answer+=$q;$carry+=$r;if($carry>=$d){++$answer;$carry-=$d;}}$b=intdiv($b,2);if(!$b)break;$q*=2;$r*=2;if($r>=$d){++$q;$r-=$d;}}return $answer;}
 public static function normalize(array $data):array{
  $out=[];foreach(['buyer_name'=>200,'buyer_street'=>200,'buyer_postcode'=>20,'buyer_city'=>150,'buyer_email'=>254,'buyer_reference'=>180,'description'=>300,'note'=>3000,'vat_reason'=>500] as $key=>$limit)$out[$key]=self::text($data,$key,$limit,!in_array($key,['note','vat_reason','buyer_email','buyer_reference'],true));
  if($out['buyer_email']!==''&&!filter_var($out['buyer_email'],FILTER_VALIDATE_EMAIL))throw new DomainException('E-Mail des Rechnungsempfängers prüfen.');
  $out['seller_contact']=self::text($data,'seller_contact',180,false);$out['domestic_confirmed']=in_array($data['domestic_confirmed']??false,[true,'1'],true);$out['invoice_format']=$data['invoice_format']??'hybrid-xrechnung';
  if(!is_string($out['invoice_format'])||!in_array($out['invoice_format'],['pdf','hybrid-xrechnung'],true))throw new DomainException('Rechnungsformat ausdrücklich auswählen.',422);
  foreach(['document_date','due_date','delivery_date'] as $key)$out[$key]=self::date(self::text($data,$key,10));if($out['due_date']<$out['document_date'])throw new DomainException('Fälligkeit darf nicht vor dem Rechnungsdatum liegen.');
  $out['category']=self::text($data,'category',30);if(!isset(Finance::CATEGORIES[$out['category']]))throw new DomainException('Rechnungszweck wählen.');
  $out['contact_id']=self::text($data,'contact_id',32,false);$out['payment_account']=self::text($data,'payment_account',32,false);$rows=$data['positions']??null;if(!is_array($rows)||!array_is_list($rows)||count($rows)<1||count($rows)>50)throw new DomainException('Eine bis 50 Rechnungspositionen erfassen.');$out['positions']=[];$out['total_cents']=0;
  foreach($rows as $p){if(!is_array($p))throw new DomainException('Position prüfen.');$description=self::text($p,'description',300);$quantity=self::quantity(self::text($p,'quantity',15));$unit=self::text($p,'unit',3);if(!isset(self::UNITS[$unit]))throw new DomainException('Einheit auswählen.');$price=Finance::cents(self::text($p,'unit_gross',30));$rate=self::text($p,'tax_rate',2);if(!in_array($rate,['0','7','19'],true)||$price<1||$price>100000000)throw new DomainException('Bruttopreis und Umsatzsteuer prüfen.');$gross=intdiv($price*$quantity+500,1000);if($gross<1||$out['total_cents']+$gross>100000000000)throw new DomainException('Positionsbetrag liegt außerhalb des zulässigen Bereichs.');$tax=$rate==='0'?0:intdiv($gross*(int)$rate+intdiv(100+(int)$rate,2),100+(int)$rate);$sphere=self::text($p,'sphere',2,false);$account=self::text($p,'account',5,false);if($sphere!==''&&TaxCatalog::sphereOf($sphere)==='')throw new DomainException('Vereinsbereich prüfen.');if($rate==='0'&&$out['vat_reason']==='')throw new DomainException('Bei 0 % den tatsächlichen Grund der Steuerbefreiung angeben, zum Beispiel Kleinunternehmerregelung nach § 19 UStG.');$out['positions'][]=compact('description','quantity','unit','price','gross','tax','rate','sphere','account');$out['total_cents']+=$gross;}
  return $out;
 }
 public function get(string $id,bool $lock=false):array{if($lock&&!$this->db->inTransaction())throw new DomainException('Aktuelle Rechnungsprüfung benötigt eine bestehende Transaktion.',503);$a=$this->access();$r=$this->q('SELECT * FROM outgoing_invoices WHERE club_id=? AND id=?'.($lock?' FOR UPDATE NOWAIT':''),[$a['club_id'],$id])->fetch();if(!$r)throw new DomainException('Ausgangsrechnung nicht verfügbar.',404);$r['data']=json_decode($r['payload'],true,512,JSON_THROW_ON_ERROR);$r['delivery']=$this->q('SELECT state,recipient,updated_at,error FROM outgoing_invoice_deliveries WHERE club_id=? AND invoice_id=?',[$a['club_id'],$id])->fetch()?:null;return $r;}
 public function listing():array{$a=$this->access();return $this->q('SELECT id,kind,state,version,number,payload,issued_at FROM outgoing_invoices WHERE club_id=? ORDER BY created_at DESC,id DESC LIMIT 500',[$a['club_id']])->fetchAll();}
 private function history(array $r,string $action):void{$a=$this->access(true);$this->q('INSERT INTO outgoing_invoice_history VALUES(?,?,?,?,?,?,?)',[$a['club_id'],$r['id'],$r['version'],$action,$a['id'],gmdate('c'),$r['payload']]);$this->q('INSERT INTO audit_events(club_id,actor_id,action,object_id,object_version,happened_at) VALUES(?,?,?,?,?,?)',[$a['club_id'],$a['id'],'outgoing.'.$action,$r['id'],$r['version'],gmdate('c')]);}
 private function sources(array $data):void{$a=$this->access(true);if($data['contact_id']!==''&&!$this->q("SELECT 1 FROM contacts WHERE club_id=? AND id=? AND archived_at IS NULL FOR SHARE NOWAIT",[$a['club_id'],$data['contact_id']])->fetchColumn())throw new DomainException('Empfängerkontakt nicht verfügbar.');if($data['payment_account']!=='')(new Finance($this->db,$this->actor))->requireActiveAccount($data['payment_account']);}
 public function save(string $id,int $version,array $data,string $key):string{return $this->write(function()use($id,$version,$data,$key){$a=$this->access(true);$normalized=self::normalize($data);$this->sources($normalized);$json=json_encode($normalized,JSON_THROW_ON_ERROR|JSON_UNESCAPED_UNICODE);if($id!==''){$old=$this->get($id,true);if(!in_array($old['state'],['draft','reviewed'],true)||(int)$old['version']!==$version||$old['kind']!=='invoice')throw new DomainException('Rechnung geändert oder bereits ausgegeben. Ausgegebene Rechnungen nur mit Storno oder Gutschrift korrigieren.',409);$this->q("UPDATE outgoing_invoices SET payload=?,state='draft',reviewed_hash='',version=version+1 WHERE club_id=? AND id=?",[$json,$a['club_id'],$id]);}else{if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new DomainException('Formular neu öffnen.');$prior=$this->q('SELECT id,payload FROM outgoing_invoices WHERE club_id=? AND request_key=?',[$a['club_id'],$key])->fetch();if($prior){if(!hash_equals($prior['payload'],$json))throw new DomainException('Formular bereits mit anderen Angaben gespeichert.');return $prior['id'];}$id=bin2hex(random_bytes(16));$this->q("INSERT INTO outgoing_invoices(club_id,id,kind,state,payload,created_by,created_at,request_key) VALUES(?,?,'invoice','draft',?,?,?,?)",[$a['club_id'],$id,$json,$a['id'],gmdate('c'),$key]);}$this->history($this->get($id),'saved');return $id;});}
 private function stale(array $r,int $version,string $state):void{if((int)$r['version']!==$version||$r['state']!==$state)throw new DomainException('Stand wurde verändert. Bitte neu öffnen und prüfen.',409);}
 private function validateBank(array $data,array $issuer):void{$bank=$issuer['bank'];Iban::normalize((string)($bank['iban']??''));if(trim($bank['holder']??'')===''||($bank['account_id']??'')==='')throw new DomainException('Die Rechnungsbankverbindung mit Kontoinhaber und Finanzkonto in den Vereinsdaten vervollständigen.');(new Finance($this->db,$this->actor))->requireActiveAccount($bank['account_id']);if($data['payment_account']!==''&&$data['payment_account']!==$bank['account_id'])throw new DomainException('Das Zahlungskonto muss zur hinterlegten Rechnungsbankverbindung gehören. Diese bei Bedarf in den Vereinsdaten ändern.');}
 private function issuer():array{$a=$this->access();$get=function($name)use($a){$r=$this->q('SELECT payload FROM club_settings WHERE club_id=? AND section=?'.($this->db->inTransaction()?' FOR SHARE NOWAIT':''),[$a['club_id'],$name])->fetchColumn();return array_replace(SettingsSchema::defaults($name),$r?json_decode($r,true,512,JSON_THROW_ON_ERROR):[]);};return ['club'=>$get('club'),'tax'=>$get('tax'),'bank'=>$get('bank'),'paper'=>$get('paper'),'texts'=>$get('texts_invoices')];}
 public function review(string $id,int $version):void{$this->tx(function()use($id,$version){$r=$this->get($id,true);$this->stale($r,$version,'draft');$this->sources($r['data']);$issuer=$this->issuer();$this->validateBank($r['data'],$issuer);foreach(['name','street','postcode','city'] as $k)if(trim($issuer['club'][$k]??'')==='')throw new DomainException('Vereinsdaten vervollständigen: '.$k.'.');if(trim($issuer['tax']['number']??'')==='')throw new DomainException('Steuernummer in den Vereinsdaten hinterlegen.');$doc=$this->document($r,'ENTWURF',$issuer);$reviewInvoice=$r;$reviewInvoice['number']='ENTWURF';$reviewInvoice['data']['issuer']=$issuer;$preview=DocumentPreview::pdf($doc);if(($r['data']['invoice_format']??'')!=='pdf')IssuedInvoiceFile::xml($reviewInvoice,$preview);$hash=hash('sha256',$r['payload'].json_encode($issuer,JSON_THROW_ON_ERROR));$this->q("UPDATE outgoing_invoices SET state='reviewed',reviewed_hash=?,version=version+1 WHERE club_id=? AND id=?",[$hash,$r['club_id'],$id]);$this->history($this->get($id),'reviewed');});}
 private function document(array $r,string $number,array $issuer):array{
  $d=$r['data'];$c=$issuer['club'];$bank=$issuer['bank'];$paper=$issuer['paper'];$paper['sender_name']=$c['name'];$paper['sender_street']=$c['street'];$paper['sender_city']=trim(($c['postcode']??'').' '.($c['city']??''));$paper['sender_address2']=$c['address2']??'';$paper['show_delivery']=true;
  $money=fn($n)=>number_format($n/100,2,',','.').' €';$values=array_fill_keys(array_keys(SettingsSchema::VARIABLES),'');$values=array_replace($values,['VEREINSNAME'=>$c['name'],'VEREINS_IBAN'=>$bank['iban']??'','VEREINS_BIC'=>$bank['bic']??'','KONTOINHABER'=>$bank['holder']??'','RECHNUNGSNUMMER'=>$number,'VERWENDUNGSZWECK'=>$number,'RECHNUNGSDATUM'=>date('d.m.Y',strtotime($d['document_date'])),'DATUM'=>date('d.m.Y',strtotime($d['document_date'])),'LIEFERDATUM'=>date('d.m.Y',strtotime($d['delivery_date'])),'FAELLIGKEIT'=>date('d.m.Y',strtotime($d['due_date'])),'ZAHLBETRAG'=>$money($d['total_cents']),'BEZEICHNUNG'=>$d['description'],'BRIEFANREDE'=>'Guten Tag '.$d['buyer_name'].',']);$text=$issuer['texts']['invoice'];foreach(['subject','message','intro','closing'] as $key)$text[$key]=SettingsSchema::interpolate($text[$key],$values);foreach(['footer_left','footer_middle','footer_right'] as $key)$paper[$key]=SettingsSchema::interpolate($paper[$key],$values);
  $text['intro']=trim(($d['note']!==''?$d['note']."\n\n":'').$text['intro']);$text['closing'].="\nSteuernummer: ".($issuer['tax']['number']??'');if($d['vat_reason']!=='')$text['closing'].="\n".$d['vat_reason'];$assets=[];if(($paper['logo']??'')!==''){$asset=Settings\PaperAssets::load($this->db,$r['club_id'],$paper['logo']);$assets['logo']=['mime'=>$asset['mime'],'base64'=>base64_encode($asset['bytes'])];}
  $rows=[];$tax=0;foreach($d['positions'] as $p){$tax+=$p['tax'];$rows[]=['description'=>$p['description'],'quantity'=>str_replace('.',',',self::quantityText($p['quantity'])),'unit'=>$p['unit_label']??self::UNITS[$p['unit']],'tax'=>$p['rate'].' %','gross'=>$money($p['gross'])];}$title=match($r['kind']){'credit'=>'Gutschrift','cancellation'=>'Stornorechnung',default=>'Rechnung'}.' '.$number;
  return ['kind'=>'invoice','general_invoice'=>true,'draft'=>$number==='ENTWURF','paper'=>$paper,'values'=>$values,'text'=>$text,'assets'=>$assets,'title'=>$title,'recipient'=>$d['buyer_name']."\n".$d['buyer_street']."\n".$d['buyer_postcode'].' '.$d['buyer_city'],'recipient_email'=>$d['buyer_email'],'date'=>date('d.m.Y',strtotime($d['document_date'])),'delivery_date'=>date('d.m.Y',strtotime($d['delivery_date'])),'positions'=>$rows,'net'=>$money($d['total_cents']-$tax),'tax'=>$money($tax),'gross'=>$money($d['total_cents']),'payment_reference'=>$r['kind']==='invoice'?$number:''];
 }
 public function preview(string $id):array{$r=$this->get($id);if($r['document_id']){$file=(new Documents($this->db,$this->actor))->file($r['document_id'],1);return json_decode($file['snapshot'],true,512,JSON_THROW_ON_ERROR);}return $this->document($r,'ENTWURF',$this->issuer());}
 /** Native reads bind the current saved draft, or the exact currently accessible original. */
 public function currentPreview(string $id,bool $originalOnly=false):array{
  $own=!$this->db->inTransaction();
  try{
   if($own)$this->db->exec('START TRANSACTION');$actor=$this->access();
   $r=$this->q('SELECT * FROM outgoing_invoices WHERE club_id=? AND id=? FOR SHARE NOWAIT',[$actor['club_id'],$id])->fetch();
   if(!$r)throw new DomainException('Ausgangsrechnung nicht verfügbar.',404);
   if($originalOnly&&!$r['document_id'])throw new DomainException('Die E-Rechnung ist noch nicht ausgestellt.');
   $r['data']=json_decode($r['payload'],true,64,JSON_THROW_ON_ERROR);
   if($r['document_id']){
    $original=(new Documents($this->db,$this->actor))->currentFinancialOriginal($r['document_id'],1);
    if($original['trashed'])throw new DomainException('Ursprüngliches Rechnungs-PDF zuerst aus dem Papierkorb wiederherstellen.',409);
    $file=$this->q('SELECT * FROM document_files WHERE club_id=? AND document_id=? AND revision=1 FOR SHARE NOWAIT',[$actor['club_id'],$r['document_id']])->fetch();
    if(!$file||$file['sha256']!==$original['file']['sha256']||!hash_equals($file['sha256'],hash('sha256',$file['bytes']))||!str_starts_with($file['bytes'],'%PDF-'))throw new DomainException('Ursprüngliches Rechnungs-PDF bitte prüfen lassen.',503);
    $result=['invoice'=>$r,'document'=>json_decode($file['snapshot'],true,64,JSON_THROW_ON_ERROR),'bytes'=>$file['bytes'],'sha256'=>$file['sha256']];
   }else{
    $issuer=$this->issuer();$document=$this->document($r,'ENTWURF',$issuer);$bytes=DocumentPreview::pdf($document);
    $result=['invoice'=>$r,'document'=>$document,'bytes'=>$bytes,'sha256'=>hash('sha256',$bytes)];
   }
   if($own)$this->db->commit();return $result;
  }catch(\Throwable$failure){
   if($own&&$this->db->inTransaction())$this->db->rollBack();
   if($failure instanceof \PDOException&&in_array((int)($failure->errorInfo[1]??0),[1205,3572],true))throw new DomainException('Ausgangsrechnung wird gerade bearbeitet. Bitte erneut prüfen.',503,$failure);
   throw $failure;
  }
 }
 public function xml(string $id):string{
  $original=$this->currentPreview($id,true);$r=$original['invoice'];
  $proof=$original['document']['einvoice']??[];$xml=$proof['xml']??'';
  if(!is_string($xml)||$xml===''||($proof['kosit']['state']??'')!=='valid'||($proof['validation']['state']??'')!=='valid'||!hash_equals((string)($proof['xml_sha256']??''),hash('sha256',$xml))||!hash_equals((string)($proof['validation']['sha256']??''),hash('sha256',$original['bytes'])))throw new DomainException('Für dieses Original liegt keine geprüfte eingebettete E-Rechnung vor.');
  return $xml;
 }
 private function storePdf(array $r,array $doc,string $bytes):string{
  $a=$this->access(true);$source=DocumentCatalog::register($this->db,$a['club_id'],'entry',$r['entry_id']);$id=bin2hex(random_bytes(16));$now=gmdate('c');$this->q("INSERT INTO documents(club_id,id,folder_id,title,kind,document_date,scopes,origin,created_at,created_by) VALUES(?,?,?,?,'invoice',?,'[\"finance\"]','generated',?,?)",[$a['club_id'],$id,$source['folder_id'],$doc['title'],$r['data']['document_date'],$now,$a['id']]);$q=$this->db->prepare('INSERT INTO document_files(club_id,document_id,revision,name,mime,bytes,sha256,created_at,created_by,snapshot) VALUES(?,?,1,?,?,?,?,?,?,?)');$args=[$a['club_id'],$id,'rechnung-'.preg_replace('/[^a-zA-Z0-9_-]/','-',$r['number']).'.pdf','application/pdf',$bytes,hash('sha256',$bytes),$now,$a['id'],json_encode($doc,JSON_THROW_ON_ERROR)];foreach($args as $i=>$v)$q->bindValue($i+1,$v,$i===4?PDO::PARAM_LOB:PDO::PARAM_STR);$q->execute();$this->q("INSERT INTO document_links VALUES(?,?,'entry',?)",[$a['club_id'],$id,$r['entry_id']]);$this->q('INSERT INTO document_history(club_id,document_id,actor_id,action,version,happened_at,details) VALUES(?,?,?,\'outgoing.issued\',1,?,?)',[$a['club_id'],$id,$a['id'],$now,json_encode(['invoice'=>$r['id'],'kind'=>$r['kind']],JSON_THROW_ON_ERROR)]);return $id;
 }
 public function issue(string $id,int $version):string{return $this->tx(function()use($id,$version){$r=$this->get($id,true);if($r['state']==='issued'&&(int)$r['version']===$version+1)return $r['entry_id'];$this->stale($r,$version,'reviewed');$issuer=$this->issuer();if(!hash_equals($r['reviewed_hash'],hash('sha256',$r['payload'].json_encode($issuer,JSON_THROW_ON_ERROR))))throw new DomainException('Vereins- oder Rechnungsdaten geändert. Entwurf speichern und erneut prüfen.');$this->sources($r['data']);$this->validateBank($r['data'],$issuer);$data=$r['data'];$positions=[];foreach($data['positions'] as $p)$positions[]=['description'=>$p['description'],'amount'=>self::amount($p['gross']),'tax_rate'=>$p['rate'],'sphere'=>$p['sphere'],'account'=>$p['account']];$f=new Finance($this->db,$this->actor);$entry=$f->createOutgoingEntryLocked(['kind'=>'income','description'=>$data['description'],'counterparty'=>$data['buyer_name'],'category'=>$data['category'],'document_date'=>$data['document_date'],'due_date'=>$data['due_date'],'positions'=>$positions,'notes'=>'Ausgangsrechnung'],substr(hash('sha256','outgoing:'.$r['club_id'].':'.$id),0,32));$r['entry_id']=$entry;$r['number']=$f->entry($entry)['display_number'];$r['data']['issuer']=$issuer;$doc=$this->document($r,$r['number'],$issuer);$built=IssuedInvoiceFile::build($r,$doc);$document=$this->storePdf($r,$built['document'],$built['bytes']);$this->q("UPDATE outgoing_invoices SET state='issued',entry_id=?,number=?,document_id=?,issued_at=?,payload=?,version=version+1 WHERE club_id=? AND id=?",[$entry,$r['number'],$document,gmdate('c'),json_encode($r['data'],JSON_THROW_ON_ERROR),$r['club_id'],$id]);$this->history($this->get($id),'issued');return $entry;});}
 public function queue(string $id,int $version,?array $input=null,?string $previousHash=null):void
 {
  $this->write(function()use($id,$version,$input,$previousHash):void{
   $r=$this->get($id,true);$this->stale($r,$version,'issued');$email=$r['data']['buyer_email'];if(!filter_var($email,FILTER_VALIDATE_EMAIL))throw new DomainException('Keine gültige E-Mail im ausgegebenen Empfängerstand. PDF bitte per Post übermitteln.',422);
   $old=$this->q('SELECT * FROM outgoing_invoice_deliveries WHERE club_id=? AND invoice_id=? FOR UPDATE NOWAIT',[$r['club_id'],$id])->fetch()?:null;
   if($old&&$previousHash===null){if($input!==null)throw new DomainException('Für dieses Original liegt bereits ein Versandauftrag vor. Den vorhandenen Stand öffnen.',409);return;}
   if($old){if($old['state']!=='blocked'||!is_string($previousHash)||!hash_equals(hash('sha256',OutgoingMailMessage::json($old)),$previousHash))throw new DomainException('Den tatsächlich gestoppten ursprünglichen Versandauftrag erneut öffnen.',409);}
   elseif($previousHash!==null)throw new DomainException('Der vorher geprüfte Versandauftrag ist nicht mehr vorhanden.',409);
   $context=OutgoingMailContext::read($this->db,$this->actor,$id);$input??=OutgoingMailInput::initial($context);
   if($input['invoice']!==$id||(int)$input['version']!==$version||$input['kind']!==($old?'replace':'queue'))throw new DomainException('Eigenen geprüften Rechnungs-Mailentwurf auswählen.',409);
   $message=OutgoingMailMessage::make($context,$input);$now=gmdate('c');
   if($old){$updated=$this->q("UPDATE outgoing_invoice_deliveries SET subject=?,body=?,actor_id=?,state='pending',error='',updated_at=? WHERE club_id=? AND invoice_id=? AND state='blocked'",[$message['subject'],$message['body'],$this->actor,$now,$r['club_id'],$id]);if($updated->rowCount()!==1)throw new DomainException('Versandauftrag inzwischen geändert. Bitte erneut prüfen.',409);}
   else$this->q("INSERT INTO outgoing_invoice_deliveries(club_id,invoice_id,recipient,subject,body,document_id,document_sha256,actor_id,state,updated_at) VALUES(?,?,?,?,?,?,?,?,'pending',?)",[$r['club_id'],$id,$email,$message['subject'],$message['body'],$r['document_id'],$context['file']['sha256'],$this->actor,$now]);
   $this->q('INSERT INTO audit_events(club_id,actor_id,action,object_id,object_version,happened_at) VALUES(?,?,?,?,?,?)',[$r['club_id'],$this->actor,$old?'outgoing.mail.replaced':'outgoing.mail.queued',$id,$version,$now]);
  });
 }
 private function correctionPlan(array $old,int $version,string $kind,string $amount,string $reason,string $date,string $requestHash,?array $currentCorrection=null):array{
  $this->stale($old,$version,'issued');if($old['kind']!=='invoice'||!in_array($kind,['cancellation','credit'],true))throw new DomainException('Nur eine Originalrechnung kann korrigiert werden.');$reason=trim($reason);if($reason===''||mb_strlen($reason)>1000)throw new DomainException('Korrekturgrund angeben und Formular neu öffnen.');self::date($date);if($date<$old['data']['document_date']||$date>date('Y-m-d'))throw new DomainException('Korrekturdatum zwischen Originaldatum und heute wählen.');$currentCorrection??=\Kulturhus\Verein\Finance\Invoices\OutgoingCorrectionSource::read($this->db,$this->actor,$old['id']);$e=$currentCorrection['entry'];$prior=$currentCorrection['credits'];$credited=0;$creditedRows=[];foreach($prior as $priorRow){$previous=json_decode($priorRow['payload'],true,512,JSON_THROW_ON_ERROR);$credited+=$previous['total_cents'];foreach($previous['positions'] as $priorPosition){$ordinal=(int)$priorPosition['original_ordinal'];$creditedRows[$ordinal]['gross']=($creditedRows[$ordinal]['gross']??0)+$priorPosition['gross'];$creditedRows[$ordinal]['tax']=($creditedRows[$ordinal]['tax']??0)+$priorPosition['tax'];}}$cents=$kind==='credit'?Finance::cents($amount):0;if($kind==='cancellation'){if($e['allocated_cents']||$credited||$e['status']==='cancelled'||$e['reversed_on'])throw new DomainException('Storno nur für eine unbezahlte Rechnung ohne Gutschrift. Bei Zahlung eine Gutschrift für die tatsächliche Erstattung erstellen.');$cents=$old['data']['total_cents'];}elseif($cents<=0||$cents>(int)$e['allocated_cents']-$credited)throw new DomainException('Gutschrift darf den noch nicht gutgeschriebenen Zahlungseingang nicht übersteigen.');
   $new=$old;$new['id']='';$new['kind']=$kind;$new['data']['correction_request']=$requestHash;$new['data']['original_number']=$old['number'];$new['data']['original_date']=$old['data']['document_date'];$new['data']['document_date']=$date;$new['data']['due_date']=$date;$new['data']['note']='Zu Rechnung '.$old['number'].': '.$reason;$new['data']['total_cents']=$cents;$new['data']['description']=($kind==='credit'?'Gutschrift':'Storno').' zu '.$old['number'];$distributed=0;$cumulative=0;$original=$old['data']['total_cents']-$credited;$rows=[];foreach($old['data']['positions'] as $i=>$p){$remainingGross=$p['gross']-($creditedRows[$i]['gross']??0);$remainingTax=$p['tax']-($creditedRows[$i]['tax']??0);$cumulative+=$remainingGross;$next=self::proportion($cents,$cumulative,$original);$value=$next-$distributed;$distributed=$next;if($value<=0)continue;$p['original_ordinal']=$i;$p['gross']=$value;if($kind==='credit'){$p['quantity']=1000;$p['unit']='C62';$p['unit_label']='Anteil';$p['price']=$value;}$p['tax']=$value===$remainingGross?$remainingTax:min($remainingTax,self::proportion($value,$remainingTax,$remainingGross));$rows[]=$p;}$new['data']['positions']=$rows;$positions=array_map(fn($p)=>['description'=>$p['description'],'amount'=>self::amount($p['gross']),'tax_rate'=>$p['rate'],'sphere'=>$p['sphere'],'account'=>$p['account'],'input_tax'=>'none'],$rows);
  return ['invoice'=>$new,'positions'=>$positions,'normalized'=>['kind'=>$kind,'amount_cents'=>$cents,'reason'=>$reason,'date'=>$date],'source'=>$currentCorrection['source']];
 }
 private function correctionDocument(array $new,string $kind):array{
  $doc=$this->document($new,$new['number'],$new['data']['issuer']);$doc['text']['intro']=$new['data']['note']."\n\n".($kind==='credit'?'Die folgenden Beträge werden gutgeschrieben:':'Die folgenden Positionen werden storniert:');$doc['text']['closing']=$kind==='credit'?'Diese Gutschrift mindert die berechnete Leistung. Eine Erstattung wird gesondert als tatsächliche Zahlung zugeordnet.':'Die oben genannte Rechnung wird vollständig storniert. Es entsteht keine Zahlung.';$doc['text']['closing'].="\nSteuernummer: ".($new['data']['issuer']['tax']['number']??'');if($new['data']['vat_reason']!=='')$doc['text']['closing'].="\n".$new['data']['vat_reason'];return $doc;
 }
 /** A real unnumbered correction preview, without a financial entry or archive write. */
 public function correctionPreview(string $id,int $version,string $kind,string $amount,string $reason,string $date):array{
  $own=!$this->db->inTransaction();
  try{
   if($own)$this->db->exec('START TRANSACTION');
   $source=\Kulturhus\Verein\Finance\Invoices\OutgoingCorrectionSource::read($this->db,$this->actor,$id);
   $requestHash=hash('sha256',json_encode([$id,$version,$kind,$amount,trim($reason),$date],JSON_THROW_ON_ERROR));
   $plan=$this->correctionPlan($source['invoice'],$version,$kind,$amount,$reason,$date,$requestHash,$source);
   $invoice=$plan['invoice'];$invoice['id']=$id;$invoice['number']='ENTWURF';
   $document=$this->correctionDocument($invoice,$kind);$bytes=DocumentPreview::pdf($document);
   if(($invoice['data']['invoice_format']??'')==='hybrid-xrechnung')IssuedInvoiceFile::xml($invoice,$bytes);
   $result=['input'=>['invoice'=>$id,'version'=>$version,'kind'=>$kind,'amount'=>$amount,'reason'=>$reason,'date'=>$date],'normalized'=>$plan['normalized'],'source'=>$plan['source'],'document'=>$document,'bytes'=>$bytes,'sha256'=>hash('sha256',$bytes)];
   if($own)$this->db->commit();return $result;
  }catch(\Throwable $failure){if($own&&$this->db->inTransaction())$this->db->rollBack();if($failure instanceof \PDOException&&in_array((int)($failure->errorInfo[1]??0),[1205,3572],true))throw new DomainException('Rechnung oder Korrektur wird gerade bearbeitet. Bitte erneut prüfen.',503,$failure);throw $failure;}
 }
 public function correct(string $id,int $version,string $kind,string $amount,string $reason,string $date,string $key):string{return $this->tx(function()use($id,$version,$kind,$amount,$reason,$date,$key){$old=$this->get($id,true);$requestHash=hash('sha256',json_encode([$id,$version,$kind,$amount,trim($reason),$date],JSON_THROW_ON_ERROR));$replay=$this->q('SELECT id,payload FROM outgoing_invoices WHERE club_id=? AND request_key=? FOR SHARE NOWAIT',[$old['club_id'],$key])->fetch();if($replay){$saved=json_decode($replay['payload'],true,512,JSON_THROW_ON_ERROR);if(!hash_equals((string)($saved['correction_request']??''),$requestHash))throw new DomainException('Korrekturformular bereits mit anderen Angaben verwendet.');return $replay['id'];}if(!preg_match('/^[a-f0-9]{32}$/D',$key))throw new DomainException('Korrekturgrund angeben und Formular neu öffnen.');$plan=$this->correctionPlan($old,$version,$kind,$amount,$reason,$date,$requestHash);$new=$plan['invoice'];$new['id']=bin2hex(random_bytes(16));$positions=$plan['positions'];$f=new Finance($this->db,$this->actor);
   if($kind==='credit'){$new['entry_id']=$f->createOutgoingEntryLocked(['kind'=>'expense','description'=>$new['data']['description'],'counterparty'=>$new['data']['buyer_name'],'category'=>$new['data']['category'],'document_date'=>$date,'due_date'=>$date,'positions'=>$positions,'notes'=>$new['data']['note']],$key);$new['number']=$f->entry($new['entry_id'])['display_number'];}else{$new['entry_id']=$old['entry_id'];$new['number']=Numbering::allocate($this->db,$old['club_id'],'invoice',$date,$new['id']);$this->q("UPDATE finance_entries SET status='cancelled',version=version+1 WHERE club_id=? AND id=?",[$old['club_id'],$old['entry_id']]);$this->q("UPDATE outgoing_invoices SET state='cancelled',version=version+1 WHERE club_id=? AND id=?",[$old['club_id'],$id]);$this->q("UPDATE outgoing_invoice_deliveries SET state='cancelled' WHERE club_id=? AND invoice_id=? AND state='pending'",[$old['club_id'],$id]);$this->history($this->get($id),'cancelled');}
   $doc=$this->correctionDocument($new,$kind);$built=($old['data']['invoice_format']??'')==='hybrid-xrechnung'?IssuedInvoiceFile::build($new,$doc):['document'=>$doc,'bytes'=>DocumentPreview::pdf($doc)];$document=$this->storePdf($new,$built['document'],$built['bytes']);$this->q("INSERT INTO outgoing_invoices(club_id,id,kind,parent_id,state,payload,entry_id,document_id,number,created_by,created_at,issued_at,request_key) VALUES(?,?,?,?,'issued',?,?,?,?,?,?,?,?)",[$old['club_id'],$new['id'],$kind,$id,json_encode($new['data'],JSON_THROW_ON_ERROR),$kind==='credit'?$new['entry_id']:null,$document,$new['number'],$this->actor,gmdate('c'),gmdate('c'),$key]);$this->history($this->get($new['id']),'issued');return $new['id'];});}
 /** The short claim transaction ends before any transport callback begins. */
 private function claimMessage(array $pending):?array
 {
  return $this->write(function()use($pending):?array{
   $current=$this->q('SELECT * FROM outgoing_invoice_deliveries WHERE club_id=? AND invoice_id=? FOR UPDATE NOWAIT',[$pending['club_id'],$pending['invoice_id']])->fetch();
   if(!$current||$current!==$pending||$current['state']!=='pending')return null;
   $context=OutgoingMailContext::read($this->db,$this->actor,$current['invoice_id']);
   if($context['invoice']['document_id']!==$current['document_id']||$context['invoice']['data']['buyer_email']!==$current['recipient']||!hash_equals($current['document_sha256'],$context['file']['sha256']))throw new DomainException('Versandstand geändert.',409);
   $message=OutgoingMailMessage::open($current);
   if($message['format']===OutgoingMailMessage::FORMAT&&!hash_equals($message['payment_source_sha256'],hash('sha256',OutgoingMailMessage::json($context['payment']??[]))))throw new DomainException('Zahlungsstand inzwischen geändert.',409);
   $claim=$this->q("UPDATE outgoing_invoice_deliveries SET state='sending',updated_at=? WHERE club_id=? AND invoice_id=? AND state='pending'",[gmdate('c'),$current['club_id'],$current['invoice_id']]);
   return $claim->rowCount()===1?['message'=>$message,'file'=>$context['file']]:null;
  });
 }
 private static function blockPendingMessage(PDO $db,array $pending):void
 {
  // A rejection of an older observed row cannot stop a newly approved replacement.
  DocumentCatalog::query($db,"UPDATE outgoing_invoice_deliveries SET state='blocked',error='Berechtigung, Rechnung oder Anhang geändert.' WHERE club_id=? AND invoice_id=? AND state='pending' AND recipient=? AND BINARY subject=? AND BINARY body=? AND document_id=? AND document_sha256=? AND actor_id=? AND updated_at=? AND BINARY error=?",[$pending['club_id'],$pending['invoice_id'],$pending['recipient'],$pending['subject'],$pending['body'],$pending['document_id'],$pending['document_sha256'],$pending['actor_id'],$pending['updated_at'],$pending['error']]);
 }
 public static function dispatch(PDO $db,string $url,callable $send,?string $club=null):int
 {
  if(!MailPolicy::allowed($url))return 0;
  if($db->inTransaction())throw new DomainException('Rechnungsversand benötigt einen eigenen abgeschlossenen Speichervorgang.',503);
  DocumentCatalog::query($db,"UPDATE outgoing_invoice_deliveries SET state='uncertain',error='Versand unterbrochen. Zustellung prüfen.' WHERE state='sending' AND updated_at<?".($club!==null?' AND club_id=?':''),$club!==null?[gmdate('c',time()-900),$club]:[gmdate('c',time()-900)]);
  $sent=0;
  foreach(DocumentCatalog::query($db,"SELECT * FROM outgoing_invoice_deliveries WHERE state='pending'".($club!==null?' AND club_id=?':'')." ORDER BY updated_at LIMIT 20",$club!==null?[$club]:[])as$row){
   try{$claimed=(new self($db,$row['actor_id']))->claimMessage($row);}
   catch(DomainException $failure){if($failure->getCode()!==503)self::blockPendingMessage($db,$row);continue;}
   if($claimed===null)continue;
   $message=$claimed['message'];$file=$claimed['file'];
   try{
    $send($row['recipient'],$row['subject'],$message['message'],OutgoingMailMessage::html($message,$url,$row['subject']),[['name'=>$file['name'],'mime'=>$file['mime'],'bytes'=>$file['bytes']]],$row['club_id']);
    $state='sent';$error='';++$sent;
   }catch(\Kulturhus\Native\Delivery\DeliveryNotStarted $failure){$state=$failure->retryable?'pending':'blocked';$error=\Kulturhus\Native\Delivery\DeliveryNotStarted::LABELS[$failure->stage];}
   catch(\Throwable){$state='uncertain';$error='Versandergebnis unklar. Zustellung vor Wiederholung prüfen.';}
   try{DocumentCatalog::query($db,"UPDATE outgoing_invoice_deliveries SET state=?,error=?,updated_at=? WHERE club_id=? AND invoice_id=? AND state='sending'",[$state,$error,gmdate('c'),$row['club_id'],$row['invoice_id']]);}
   catch(\Throwable $failure){
    $completed=DocumentCatalog::query($db,'SELECT * FROM outgoing_invoice_deliveries WHERE club_id=? AND invoice_id=?',[$row['club_id'],$row['invoice_id']])->fetch();
    $expected=$row;$expected['state']=$state;$expected['error']=$error;$expected['updated_at']=$completed['updated_at']??null;
    if(!$completed||$completed!==$expected)throw $failure;
   }
  }
  return $sent;
 }
